#' Table of placebo output.
#'
#'@description
#' `placebo_table()` Makes a summary table of estimated and placebo p values from output generated by
#' [placebo()] or [iv_placebo()], with every inference method in one table.
#'
#' @param plbo An object created by [placebo()] or [iv_placebo()].
#' @param caption An optional caption for the table.
#'
#' @return Generates a tinytable object. This gives the regression and placebo p values and the proportion
#' of placebo simulation significant at 5\% with HC inference, with BCH and IM inference as the number of
#' clusters increases, and with SCPC inference as the bound `avc` increases (when `avc` was given), with
#' `Clusters/avc` giving the number of clusters or `avc`. For [iv_placebo()] results the table has a block
#' of 2SLS rows followed by a block of Anderson-Rubin rows, and each HC and BCH row gives the first stage
#' F statistic with its inference and number of clusters; IM and SCPC rows give none.
#'  The regression confidence interval and its width are also reported. The next part of the table gives
#'  the z-score of a Moran test, using 5 nearest neighbours, the R2 of a regression of the treatment on the
#'  principal components of the tensor, and the effective range and structure of this regression's residuals.
#' @export
#'
#' @examples
#' library(spatInfer)
#' data(opportunity)
#' # Use 100 observations and 100 simulations to speed things up.
#' set.seed(123)
#' opportunity=opportunity |> dplyr::slice_sample(n=100)
#' # Use the number of splines and PCs indicated by [optimal_basis()] and turn off parallel processing.
#' plbo=placebo(mobility~single_mothers+short_commute+gini+dropout_rate+social_cap+dropout_na,
#' opportunity,
#' splines=6,
#' pc_num=15,
#' nSim=100,
#' Parallel=FALSE,
#' max_clus = 7,
#' avc=c(0.02,0.04)
#' )
#' placebo_table(plbo, caption="Placebo significance levels for single mothers variable.")


placebo_table=function(plbo, caption=""){
##plbo is output of `placebo()` or `iv_placebo()` functions.
sim_table(plbo,"placebo",caption)
}

#####Table of placebo (kind="placebo") or synthetic outcome (kind="synth") results, for least
#####squares or IV regressions, with every inference method. syn, for a placebo, is the matching
#####synth, whose p values are added as a column, with the notes of both tests.
sim_table=function(x,kind,caption,syn=NULL){
is_iv=is_iv_results(x$Results)
scpc="SCPC" %in% x$Results$SE
results=x$Results
if(!is.null(syn)){
  if(!identical(results[,c("SE","Clusters")],syn$Results[,c("SE","Clusters")]))
    stop("The placebo and synth must have the same inference methods, clusters and avc values.",call.=FALSE)
  results$`Synth p`=syn$Results$`Synth p`
  results=dplyr::relocate(results,"Synth p",.after="Plac 5%")
}
tr=table_rows(results)
rr=tr$rows |>
  dplyr::rename(Adj=SE) |>
  dplyr::mutate(dplyr::across(dplyr::where(is.numeric)&!dplyr::any_of("CI Width"),~{round(.x,3)}))   #CI widths keep their significant digits
names(rr)[2]=if(scpc) "Clusters/avc" else "Clusters"
ss=x$Spatial_Params|>
  dplyr::mutate(dplyr::across(dplyr::where(is.numeric),~{round(.x,2)}))

of=if(kind=="placebo") "the treatment on the principal components"
   else "the outcome on a quadratic in longitude and latitude"
notes=if(is.null(syn)) sim_notes(ss,kind,of,is_iv,scpc) else placebo_synth_notes(ss,syn,is_iv,scpc)
tab=tinytable::tt(rr,theme="striped",align="r",digits=3,notes=notes,caption=caption)

tab= tab |>
  tinytable::style_tt(i = 0, bold=TRUE ) |>
  tinytable::style_tt(j=1, bold=TRUE )
if(kind=="placebo") tab=tab |> tinytable::style_tt(j = c("Plac 5%"), color = "orange")
if(is_iv)
  tab=tab |>
    tinytable::group_tt(i=stats::setNames(list(1,tr$n_wald+1),c("2SLS","Anderson-Rubin"))) |>
    tinytable::style_tt(i="groupi", color="orange")   #2SLS and Anderson-Rubin headings

return(tab)
}

#####Notes of a placebo or synth table: spatial parameters of the simulated noise, and the tests shown.
sim_notes=function(ss,kind,of,is_iv,scpc){
Filter(Negate(is.null),list(
                paste0("Moran=",ss$Moran,
                       ", Structure=",ss$Structure,
                       ", Effective Range=",ss$Effective_Range,
                       ", R2=",ss$R2,"."
                       ),
                paste0(if(!is.null(ss$N)) paste0("N=",ss$N,", "),
                       "Splines=",ss$Splines,
                       ", PCs=",ss$PCs,"."
                ),
                if(is_iv) iv_notes(ss,scpc),
                paste0(if(kind=="placebo")
                         "Estimated and placebo p values and proportion of placebo regressions significant at 5%, along
                with confidence intervals, "
                       else "Estimated and synthetic outcome p values, along with confidence intervals, ",
                       "with HC inference, BCH and IM inference for each number of clusters",
                       if(scpc) ", and SCPC inference for each value of the average correlation bound avc" else "",
                       ". R2 gives the explanatory power of a regression of ",of,".")
              ))
}

#####Notes of a table of a placebo with the synth p values: the spatial parameters of the treatment
#####(and instrument) noise from the placebo, sp, and of the outcome noise from the synth.
placebo_synth_notes=function(sp,syn,is_iv,scpc){
ss=syn$Spatial_Params|>
  dplyr::mutate(dplyr::across(dplyr::where(is.numeric),~{round(.x,2)}))
Filter(Negate(is.null),list(
  paste0("Moran=",sp$Moran,", N=",sp$N,", Splines=",sp$Splines,", PCs=",sp$PCs,"."),
  paste0("Treatment: Structure=",sp$Structure,", Effective Range=",sp$Effective_Range,", R2=",sp$R2,". ",
         "Outcome: Structure=",ss$Structure,", Effective Range=",ss$Effective_Range,", R2=",ss$R2,"."),
  if(is_iv) iv_notes(sp,scpc),
  paste0("Estimated and placebo p values, proportion of placebo regressions significant at 5%, synthetic ",
         "outcome p values and confidence intervals, with HC inference, BCH and IM inference for each ",
         "number of clusters",
         if(scpc) ", and SCPC inference for each value of the average correlation bound avc" else "",
         ". Treatment R2 gives the explanatory power of a regression of the treatment on the principal ",
         "components, and outcome R2 of a regression of the outcome on a quadratic in longitude and latitude.")
))
}

#####Show the standard error label (HC, BCH, IM, SCPC) only where each block starts.
blank_repeated_se=function(results){
  n=nrow(results)
  if(n>1) results$SE[c(FALSE,results$SE[-1]==results$SE[-n])]=""
  return(results)
}

#####Results of iv_placebo() and iv_synth() have Anderson-Rubin rows.
is_iv_results=function(results) "AR HC" %in% results$SE

#####Rows of results as shown in a table, with the SE label only where each block starts. IV results
#####have a block of 2SLS rows followed by a block of Anderson-Rubin rows, whose SE labels lose their
#####"AR " prefix, and F is blank for IM and SCPC. n_wald is the number of 2SLS rows.
table_rows=function(results){
  if(!is_iv_results(results)) return(list(rows=blank_repeated_se(results),n_wald=NULL))
  is_ar=startsWith(results$SE,"AR ")
  wald=blank_repeated_se(results[!is_ar,,drop=FALSE])
  ar=results[is_ar,,drop=FALSE]
  ar$SE=sub("^AR ","",ar$SE)
  rows=rbind(wald,blank_repeated_se(ar))
  rows$F=format_F(rows$F)
  rownames(rows)=NULL
  return(list(rows=rows,n_wald=nrow(wald)))
}

#####First stage F statistics as text, blank where there is none (IM and SCPC).
format_F=function(F){
  out=rep("",length(F))
  out[!is.na(F)]=trimws(format(F[!is.na(F)],digits=3))
  return(out)
}

#####Table notes for iv_placebo() and iv_synth(): the instrument noise of placebos, the tests shown
#####and the first stage F statistics. scpc is TRUE when the table has SCPC rows.
iv_notes=function(ss,scpc=FALSE){
  inst=if("R2_Inst" %in% names(ss))
    paste0("Noise instrument: Structure=",ss$Structure_Inst,
           ", Effective Range=",ss$Effective_Range_Inst,
           ", R2=",ss$R2_Inst,". ") else ""
  paste0(inst,"2SLS estimates, then Anderson-Rubin tests of a zero treatment effect by the reduced form approach, ",
         "whose 95% confidence sets are valid however weak the instrument and can be unbounded. ",
         "F is the first stage F statistic, not given for IM",if(scpc) " or SCPC" else "",".")
}
